26	function main(): void {
27	  const body = process.env.ATOMATON_COMMENT_BODY ?? "";
28	  const { agent, control, sessionMode, error } = parseCommentCommand(body);
29	  const matched = agent ? "true" : "false";
30	
31	  const githubOutput = process.env.GITHUB_OUTPUT;
32	  if (githubOutput) {
33	    // `parsed` says this step RAN, which `matched` cannot: a step that does not run
34	    // leaves every output empty, and so does a comment with no command in it. The
35	    // guard's commands rule turns on the difference -- a comment from somebody who is
36	    // not a repository member is never read here, so it must not be refused for what it
37	    // would have asked for (#217).
38	    appendFileSync(githubOutput, `parsed=true\n`);
39	    appendFileSync(githubOutput, `matched=${matched}\nagent=${agent}\ncontrol=${control}\n`);
40	    appendFileSync(githubOutput, `session_mode=${sessionMode}\nerror=${error}\n`);
41	  }
