380	 * Ask every run in `root`'s subtree to stop, and leave `rootBody` where the person
381	 * will look.
382	 *
383	 * The root's comment is posted whether or not a run holds it: it is the answer to what
384	 * the person did, and a parent whose chain runs on its children has no run of its own
385	 * to speak for it. The tag rides along regardless, which costs nothing — a stop
386	 * request older than a run's own start is ignored by the watcher by design.
387	 *
388	 * Descendants are told where the stop came from. Nobody typed anything on them, and an
389	 * unexplained stop on an issue somebody is watching reads as a malfunction.
390	 */
391	export function requestStopAcross(
392	  repo: string,
393	  root: number,
394	  rootBody: string,
395	): SubtreeStop {
396	  const { nodes, problems } = readWorkTree(repo, root);
397	  const all = subtree(nodes, root);
398	  const stopped: number[] = [];
399	
400	  const rootNotified = commentOn(repo, root, rootBody);
401	  if (!rootNotified) problems.push(`could not post the stop request on #${root}`);
402	  else if (all.find((node) => node.number === root)?.running) stopped.push(root);
403	
404	  for (const node of nodesToStop(descendants(all, root))) {
405	    const body = [LLM_CONTEXT_TAG.write("exclude"), STOP_TAG.write("requested"), stopReachedNotice(root)].join("\n");
406	    if (commentOn(repo, node.number, body)) stopped.push(node.number);
407	    else problems.push(`could not post the stop request on #${node.number}`);
408	  }
409	
410	  return { stopped, rootNotified, problems };
411	}
412	
413	/** What a subtree-wide close did. */
414	export interface SubtreeClose extends SubtreeStop {
415	  /** The nodes that were closed, the root excluded — GitHub closed that one already. */
416	  closed: number[];
417	}
418	
419	/**
420	 * Close everything under `root`, having asked every run in it to stop.
421	 *
422	 * The root itself is not closed here: this runs on the `issues: closed` event, so it
423	 * is already closed by the time anything below happens. Stopping comes first, so a run
424	 * that is about to be closed out from under is told before it is.
425	 */
426	export function closeSubtreeUnder(repo: string, root: number, rootBody: string): SubtreeClose {
427	  const { nodes, problems } = readWorkTree(repo, root);
428	  const all = subtree(nodes, root);
429	  const stopped: number[] = [];
430	  const closed: number[] = [];
431	
432	  const rootNotified = commentOn(repo, root, rootBody);
433	  if (!rootNotified) problems.push(`could not post the stop request on #${root}`);
434	  else if (all.find((node) => node.number === root)?.running) stopped.push(root);
435	
436	  const under = descendants(all, root);
437	  for (const node of nodesToStop(under)) {
438	    const body = [LLM_CONTEXT_TAG.write("exclude"), STOP_TAG.write("requested"), closeReachedNotice(root)].join("\n");
439	    if (commentOn(repo, node.number, body)) stopped.push(node.number);
440	    else problems.push(`could not post the stop request on #${node.number}`);
441	  }
442	
443	  for (const node of nodesToClose(under)) {
444	    // A pull request is closed through its own command; `gh issue close` refuses one.
445	    const closeIt = node.kind === "pull-request"
446	      ? gh("pr", "close", String(node.number), "--repo", repo)
447	      : gh("issue", "close", String(node.number), "--repo", repo);
448	    if (closeIt.code === 0) closed.push(node.number);
449	    else problems.push(`could not close #${node.number}`);
450	  }
451	
452	  return { stopped, closed, rootNotified, problems };
453	}

